    if ($domain !== 'messages') {
        return array_map(static fn (array $row): string => $row[$columns[$locale]], $domain === 'validators' ? $validators : $security);
    }

    $catalogue = [];
    foreach ($messages as $key => $row) {
        $catalogue[$key] = $locale === 'de' ? $key : $row[$columns[$locale] - 1];
    }
    foreach ($aliases as $key => $source) {
        $catalogue[$key] = $catalogue[$source];
    }
    foreach ($special as $key => $row) {
        $catalogue[$key] = $row[$columns[$locale]];
    }

    return $catalogue;
};
